2	import type { Message } from "../types/message";
3	import type { ContentBuilder } from "./types";
4	
5	const isMessage = (v: unknown): v is Message =>
6	  typeof v === "object" && v !== null && "id" in v && "content" in v;
7	
8	/**
9	 * A `read` marks the conversation as read **up to** `target`, surfacing a
10	 * read receipt to the sender where the platform supports one.
11	 *
12	 * `space.send(read(message))` is the canonical outbound API;
13	 * `message.read()` and `space.read(message)` are sugar that delegate here.
14	 * Reads are fire-and-forget — providers handle them inside their `send`
15	 * action and the resolved value is `undefined`.
16	 *
17	 * Granularity is per-platform:
18	 *
19	 * - WhatsApp Business: per-message receipt via `markRead(target.id)`, which
20	 *   also marks every earlier message in the conversation as read.
21	 * - iMessage (remote): chat-level `chats.markRead(chatGuid)` — `target` only
22	 *   identifies the chat, and **every** unread message in it is marked read.
23	 *   Local mode rejects with `UnsupportedError` (warned and skipped).
24	 * - Telegram / Slack: silently no-op. Neither surfaces read state for bot
25	 *   conversations (Telegram bot chats are effectively auto-read), so the
26	 *   signal is vacuously satisfied — same best-effort contract as `typing`.
27	 */
28	export const readSchema = z.object({
29	  type: z.literal("read"),
30	  target: z.custom<Message>(isMessage, {
31	    message: "read target must be a Message",
32	  }),
33	});
34	
35	export type Read = z.infer<typeof readSchema>;
36	
37	export const asRead = (input: { target: Message }): Read =>
38	  readSchema.parse({ type: "read", ...input });
39	
40	/**
41	 * Construct a `read` content value marking the conversation read up to
42	 * `target`.
43	 *
44	 * Only inbound messages (those received from a user) can be marked read;
45	 * calling this with an outbound target throws at build time so the misuse
46	 * surfaces before the send pipeline runs. The target is required (not
47	 * `Message | undefined` like `unsend`): read targets come from the inbound
48	 * stream, never from a chainable `send()` result.
49	 */
50	export function read(target: Message): ContentBuilder {
51	  return {
52	    build: async () => {
53	      if (target.direction !== "inbound") {
54	        throw new Error(
55	          `read() target must be an inbound message (got direction "${target.direction}", message id "${target.id}")`
56	        );
57	      }
58	      return asRead({ target });
59	    },
60	  };
61	}
