```ts
interface MessageStreamOptions {
  readonly includeReadReceipts: boolean;
  readonly onInbound?: OnInboundMessage | undefined;
}

const toMessageItem = async (
  client: AdvancedIMessage,
  event: MessageEvent,
  phone: string,
  cursor: string,
  options: MessageStreamOptions
): Promise<ResumableStreamItem<IMessageMessage>> => {
  if (event.type === "message.received") {
    if (event.message.isFromMe) {
      return { cursor, id: event.message.guid, values: [] };
    }

    const cache = getMessageCache(client);
    const values = await toInboundMessages(client, cache, event, phone);

    // After conversion succeeds — an event skipUnmappable discards must not
    // trigger a contact-card share (and burn its 24h dedupe slot) for a
    // message that was never delivered.
    const inboundChatGuid = event.message.chatGuids?.[0];
    if (inboundChatGuid) {
      options.onInbound?.(inboundChatGuid);
    }

    return { cursor, id: event.message.guid, values };
  }

  if (event.type === "message.reactionAdded") {
    if (isEventFromCurrentAccount(event, phone)) {
      return {
        cursor,
        id: `${event.messageGuid}:reaction:${event.sequence}`,
        values: [],
      };
    }

    const cache = getMessageCache(client);
    return {
      cursor,
      id: `${event.messageGuid}:reaction:${event.sequence}`,
      values: await toReactionMessages(client, cache, event, phone),
    };
  }

  if (event.type === "message.read") {
    const id = readReceiptMessageId(event);
    // Opt-in (see `configSchema.readReceipts`): a group emits one event per
    // participant per message read, and surfacing a brand-new content type by
    // default would change behavior for every existing `for await` loop. When
    // off we still return an empty item so the cursor advances past the event
    // exactly as the old catch-all did.
    //
    // Self-suppression deliberately uses `isActorCurrentAccount`,

 not
    // `isEventFromCurrentAccount`: `isFromMe` is untrustworthy on this arm.
    // The actor check only catches a dedicated line reading in its own
    // Messages app; the load-bearing check is in `toReadReceiptMessages`,
    // which requires the resolved target to be one of our outbound messages.
    if (!options.includeReadReceipts || isActorCurrentAccount(event.actor, phone)) {
      return { cursor, id, values: [] };
    }

    const cache = getMessageCache(client);
    return {
      cursor,
      id,
      values: await toReadReceiptMessages(client, cache, event, phone),
    };
  }

  return {
    cursor,
    id: `${event.type}:${"messageGuid" in event ? event.messageGuid : "unknown"}:${event.sequence}`,
    values: [],
  };
};
```

