  client: AdvancedIMessage,
  cache: MessageCache,
  chat: string,
  targetGuid: string,
  partIndex: number | undefined,
  phone: string
): Promise<IMessageMessage | undefined> => {
  const candidate = await resolveTargetMessage(
    client,
    cache,
    chat,
    targetGuid,
    phone
