```ts
type ReadEvent = Extract<MessageEvent, { type: "message.read" }>;

/**
 * Synthetic id for a `message.read` event — shared between the stream item (the
 * dedup key across live/catch-up) and the surfaced message. `sequence` is
 * monotonic per line, so N participants reading the same message produce N
 * distinct ids, and the same event replayed through catch-up produces the id it
 * produced live.
 */
export const readReceiptMessageId = (event: ReadEvent): string =>
  `${event.messageGuid}:read:${event.sequence}`;

const asProviderRead = (target: IMessageMessage): Read =>
  readSchema.parse({ target, type: "read" });

/**
 * Convert a `message.read` event into an inbound `read` message.
 *
 * Two guards, cheapest first:
 *
 * 1. **No actor -> drop.** Unlike a membership change (where the state change
 *    itself is the payload and `sender: undefined` still carries meaning), the
 *    reader's identity *is* the payload of a receipt. A senderless receipt in a
 *    group would corrupt any "N of M have read" tally. Same call as
 *    `toReactionMessages`.
 *
 * 2. **The target must be one of ours.** `event.isFromMe` is not trustworthy
 *    here: the proto carries no comment for it on this arm, and it most
 *    plausibly describes the *underlying message* — which for a genuine receipt
 *    is ours, i.e. `true` — so keying self-suppression off it would suppress
 *    every receipt worth surfacing. The durable invariant is that a peer's
 *    receipt always points at a message we sent, so the resolved target must be
 *    `direction: "outbound"`. That also suppresses the echo of our own
 *    `chats.markRead()`, which marks *their* inbound messages.
 */
export const toReadReceiptMessages = async (
  client: AdvancedIMessage,
  cache: MessageCache,
  event: ReadEvent,
  phone: string
): Promise<IMessageMessage[]> => {
  if (!event.actor?.address) {
    return [];
  }

  const target = await resolveTargetMessage(
    client,
    cache,
    event.chatGuid,
    event.messageGuid,
    phone
  );
  if (target?.direction !== "outbound") {
    return [];
  }

  return [
    {
      // No `direction` on the envelope: the stream path defaults provider
      // records to inbound. The *target* keeps its own `direction: "outbound"`,
      // which `wrapProviderMessage` honors via `rawDirection`.
      id: readReceiptMessageId(event),
      content: asProviderRead(target),
      sender: toSenderRef(event.actor),
      space: {
        id: event.chatGuid,
        type: chatTypeFromGuid(event.chatGuid),
        phone,
      },
      // `readAt` is when the reader's device marked it read; `occurredAt` is
      // when the bridge observed it. Prefer the former — the entire value of a
      // receipt is *when*. The `??` guards an unset proto timestamp decoding to
      // `undefined` despite the non-optional TS type, the same defensive shape
      // as `dateCreated` at inbound.ts:437.
      timestamp: event.readAt ?? event.occurredAt,
    },
  ];
};
```

