39	
40	```ts
41	for await (const [space, message] of app.messages) {
42	  switch (message.content.type) {
43	    case "addMember":
44	      console.log(`${message.sender?.id ?? "someone"} added ${message.content.members.join(", ")}`);
45	      break;
